import 'dart:convert';
import 'package:shared_preferences/shared_preferences.dart';
import '../../domain/entities/profile_entities.dart';
abstract interface class ProfileDataSource { Future<ProfileStatus> status(String userId,ProfileRole role); Future<void> saveCustomer(String userId,CustomerProfileDraft draft); Future<void> saveProvider(String userId,ProviderProfileDraft draft); }
class ProfileLocalDataSource implements ProfileDataSource { final SharedPreferences prefs; const ProfileLocalDataSource(this.prefs); String _key(String id,ProfileRole role)=>'smarttrust_${role.name}_profile_$id'; @override Future<ProfileStatus> status(String id,ProfileRole role)async=>prefs.containsKey(_key(id,role))?ProfileStatus.complete:ProfileStatus.incomplete; @override Future<void> saveCustomer(String id,CustomerProfileDraft d)async{await prefs.setString(_key(id,ProfileRole.customer),jsonEncode({'fullName':d.fullName,'addressLine':d.addressLine,'city':d.city,'area':d.area,'lat':d.latitude,'lng':d.longitude,'photo':d.photoPath}));} @override Future<void> saveProvider(String id,ProviderProfileDraft d)async{await prefs.setString(_key(id,ProfileRole.provider),jsonEncode({'fullName':d.fullName,'cnic':d.cnicNumber,'area':d.area,'city':d.city,'lat':d.latitude,'lng':d.longitude,'years':d.yearsExperience,'shop':d.shopLocation,'photo':d.photoPath,'front':d.cnicFrontPath,'back':d.cnicBackPath}));}}
